// Postbuild: walks every <slug>.md endpoint generated by Astro and emits
// dist/docs-index.json — a flat array of { slug, title, content } the MCP
// server consumes to back search_docs and fetch_page. Runs after the .md
// endpoints already strip MDX, so content is plain CommonMark.
//
// Output schema (dist/docs-index.json):
//   [{ slug: "getting-started/what-is-arete", title: "What is Arete?", content: "..." }, ...]

import { readFile, writeFile, readdir } from "node:fs/promises";
import { join, relative } from "node:path";

const DIST = "dist";
const SKIP_NAMES = new Set([
  "llms.txt",
  "llms-full.txt",
  "llms-small.txt",
  "skill.md",
  "agent.md",
]);

async function* walkMarkdown(dir) {
  const entries = await readdir(dir, { withFileTypes: true });
  for (const e of entries) {
    const p = join(dir, e.name);
    if (e.isDirectory()) {
      yield* walkMarkdown(p);
    } else if (e.isFile() && p.endsWith(".md") && !SKIP_NAMES.has(e.name)) {
      yield p;
    }
  }
}

function parseFrontmatter(text) {
  const match = /^---\n([\s\S]*?)\n---\n([\s\S]*)$/.exec(text);
  if (!match) return { data: {}, body: text };
  const data = {};
  for (const line of match[1].split("\n")) {
    const m = /^([A-Za-z_][A-Za-z0-9_]*):\s*(.+)$/.exec(line);
    if (!m) continue;
    try {
      data[m[1]] = JSON.parse(m[2]);
    } catch {
      data[m[1]] = m[2];
    }
  }
  return { data, body: match[2].trim() };
}

const index = [];
for await (const file of walkMarkdown(DIST)) {
  const text = await readFile(file, "utf8");
  const { data, body } = parseFrontmatter(text);
  // Slug derives from path: dist/getting-started/what-is-arete.md -> getting-started/what-is-arete
  // Special case: dist/index.md -> "" (root)
  const rel = relative(DIST, file).replace(/\.md$/, "");
  const slug = rel === "index" ? "" : rel;
  const title =
    typeof data.title === "string" ? data.title : slug || "Untitled";
  index.push({ slug, title, content: body });
}

index.sort((a, b) => a.slug.localeCompare(b.slug));

const out = join(DIST, "docs-index.json");
await writeFile(out, JSON.stringify(index));
console.log(`[build-docs-index] wrote ${index.length} pages -> ${out}`);
